def top_errors(events, count):
    if count <= 0:
        return []

    error_counts = {}
    for level, message in events:
        if level == 'ERROR':
            error_counts[message] = error_counts.get(message, 0) + 1

    sorted_errors = sorted(error_counts.items(), key=lambda x: (-x[1], x[0]))
    return sorted_errors[:count]

import math

def elapsed(start_ns, finish_ns):
    if finish_ns < start_ns:
        raise ValueError("finish precedes start")
    return math.floor((finish_ns - start_ns) / 1e6)

def decode_record(payload):
    try:
        record = json.loads(payload.decode('utf-8'))
        if not isinstance(record, dict):
            raise ValueError("Record is not a dictionary")
        return record['record']
    except (json.JSONDecodeError, ValueError, KeyError):
        raise ValueError("Invalid JSON or missing record field")

